/**
 * The prepared request must be a Comgate request for the route the expectation names, and its hash
 * must still cover its endpoint, headers and body. Anything else is refused before any send.
 */
const checkedRoute = (
  prepared: PreparedProviderRequest,
  expected: GatewayExpectedEffect,
): Effect.Effect<Route, GatewayProviderUnavailableError> => {
  if (prepared.family !== FAMILY) {
    return Effect.fail(unavailable('comgate_prepared_request_family_mismatch'));
  }
  if (requestHashOf(prepared.endpointRef, prepared.headers, prepared.body) !== prepared.requestHash) {
    return Effect.fail(unavailable('comgate_prepared_request_hash_mismatch'));
  }
  return routeOf(prepared.endpointRef).pipe(
    Option.filter((route) => routeServes(route, expected)),
    failWhenNone(() => unavailable('comgate_prepared_request_route_mismatch')),
  );
};

/** COLLECT and REFUND carry the amount their response is checked against; a cancel uses its target's. */
const expectedAmountOf = (expected: GatewayExpectedEffect): PaymentMonetaryAmount =>
  Match.value(expected).pipe(
    Match.tag('COLLECT', ({ amount }) => amount),
    Match.tag('REFUND', ({ amount }) => amount),
    Match.tag('CANCEL_OR_VOID', ({ target }) => target.amount),
    Match.exhaustive,
  );

/** The transId inside the persisted refund body (encoded by `prepareRefund`). */
