export class ComgatePaymentService extends Context.Service<ComgatePaymentService, GatewayProviderAdapter>()(
  '@app/payment/integrations/comgate/comgate-payment.service/ComgatePaymentService',
) {}

const makeComgatePaymentService = Effect.gen(function* buildComgatePaymentService() {
  const http = yield* ProviderHttp;
  const credentials = yield* ProviderCredentialStore;

  /** The binding identity and its current COMGATE secret, as `merchant:secret` Basic authorization. */
  const authorizationOf = Effect.fn('ComgatePayment.authorization')(function* authorization(
    target: GatewayExecutionTarget,
  ) {
    const [binding, material] = yield* Effect.all(
      [comgateBindingOf(target), credentials.resolve({ family: FAMILY, secretRef: target.credentialSecretRef })],
      { concurrency: 1 },
    );
    const secret = yield* comgateSecretOf(material);
    return {
      authorize: (request: HttpClientRequest.HttpClientRequest) =>
        HttpClientRequest.basicAuth(request, binding.merchantId, secret),
      binding,
      secret,
    };
  });

  const lookupTransaction = Effect.fn('ComgatePayment.lookupTransaction')(function* lookupTransaction(
    target: GatewayExecutionTarget,
    transId: ProviderObjectId,
    expected: GatewayExpectedEffect,
  ) {
    const { authorize, binding } = yield* authorizationOf(target);
    const response = yield* http.read({
      family: FAMILY,
      request: authorize(
        HttpClientRequest.setHeader(HttpClientRequest.get(statusUrlOf(transId)), ACCEPT_JSON.name, ACCEPT_JSON.value),
      ),
    });
    const observedAt = yield* DateTime.now;
    const answer = yield* statusAnswerOf(response);
    return yield* mapComgateStatus({ answer, binding, expected, observedAt, transId });
  });

  const lookup = Effect.fn('ComgatePayment.lookup')(function* lookupComgate(
    target: GatewayExecutionTarget,
    request: GatewayLookupRequest,
  ) {
    const transId = yield* Effect.flatMap(comgateTransIdOfLookup(request.target), (found) =>
      pathTransIdOf(found, 'RETRIEVE'),
    );
    return yield* lookupTransaction(target, transId, request.expected);
  });

  /** Every cancel answer is resolved by a status lookup; a failed lookup leaves the DELETE unknown. */
  const confirmCancel = (
    target: GatewayExecutionTarget,
    transId: ProviderObjectId,
    answer: ComgateCancelAnswer,
    expected: GatewayExpectedEffect,
  ): Effect.Effect<ProviderDispatchResponse, GatewayProviderOutcomeUnknownError> =>
    lookupTransaction(target, transId, expected).pipe(
      Effect.catchTags({
        GatewayProviderResponseInvalid: () =>
          Effect.fail(outcomeUnknown(expected.operationId, 'comgate_cancel_confirmation_invalid')),
        GatewayProviderUnavailable: () =>
          Effect.fail(outcomeUnknown(expected.operationId, 'comgate_cancel_confirmation_unavailable')),
      }),
      Effect.flatMap((findings) => cancelDispatchResponse(answer, expected.operationId, findings)),
    );

  const classify = (
    target: GatewayExecutionTarget,
    prepared: PreparedProviderRequest,
    route: Route,
    expected: GatewayExpectedEffect,
    received: { readonly observedAt: DateTime.Utc; readonly response: ProviderHttpResponse },
  ): Effect.Effect<ProviderDispatchResponse, GatewayProviderOutcomeUnknownError> => {
    const { observedAt, response } = received;
    const mapped = { amount: expectedAmountOf(expected), operationId: expected.operationId };
    return Match.value(route).pipe(
      Match.tag('CREATE', () =>
        mapComgateCreateResponse({ bodyText: response.bodyText, expected: mapped, observedAt }),
      ),
      Match.tag('REFUND', () =>
        Effect.flatMap(refundTransIdOf(prepared, expected.operationId), (transId) =>
          mapComgateRefundResponse({ bodyText: response.bodyText, expected: mapped, observedAt, transId }),
        ),
      ),
      Match.tag('CANCEL', ({ transId }) =>
        confirmCancel(target, transId, classifyComgateCancelResponse(response.bodyText), expected),
      ),
      Match.exhaustive,
    );
  };

  const send = Effect.fn('ComgatePayment.send')(function* sendComgate(
    target: GatewayExecutionTarget,
    prepared: PreparedProviderRequest,
    expected: GatewayExpectedEffect,
  ) {
    const route = yield* checkedRoute(prepared, expected);
    const { authorize } = yield* authorizationOf(target);
    const response = yield* http.mutate({
      family: FAMILY,
      operationId: expected.operationId,
      request: authorize(mutationRequestOf(prepared, route)),
    });
    const observedAt = yield* DateTime.now;
    yield* mutationStatusCheck(response, expected.operationId);
    return yield* classify(target, prepared, route, expected, { observedAt, response });
  });

  const verifyNotification = Effect.fn('ComgatePayment.verifyNotification')(function* verifyComgateNotification(
    target: GatewayExecutionTarget,
    notification: Parameters<GatewayProviderAdapter['verifyNotification']>[1],
  ) {
    const { secret } = yield* authorizationOf(target);
    const verifiedAt = yield* DateTime.now;
    return yield* verifyComgatePush({ notification, secret, target, verifiedAt });
  });

  return {
    capabilities: COMGATE_CAPABILITIES,
    family: FAMILY,
    lookup,
    prepareCancel,
    prepareCollect,
    prepareRefund,
    replay,
    send,
    verifyNotification,
  } satisfies GatewayProviderAdapter;
});

export const ComgatePaymentServiceLive = Layer.effect(ComgatePaymentService, makeComgatePaymentService);
